select public.admin_notify('🔎 D57: Required actions khaali, App ID mila', 'Screenshots confirm: Required actions tab khaali (koi pending action nahi). Settings→Basic me App ID 4146723002296306 dikha; Privacy Policy URL aur Category khaali. Research se confirm: Development mode me OAuth dialog sirf un FB accounts ke liye khulta hai jinhe app role ho, warna wahi "App not active" page aata hai. Owner ko sequence diya: (1) usi Chrome me facebook.com kholkar dekho login developer-account hai ya nahi; (2) App roles→Roles me wahi account Admin dikhe; (3) Settings→Basic me Privacy Policy URL (hosted page) + Category Games bharo, Save; (4) Login URL retry; (5) fir bhi block ho to App Mode Development→Live karo (own-business app ⇒ App Review zaroori nahi, dono IG accounts Instagram Tester rahenge) phir retry; (6) grant ke baad section 2 se tokens generate+copy, App Secret Show, char lines Drive private meta-connect-codes.txt me.', 'session_end') as notified;
